command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="559dc5266f16218af5613bfe9d7e7b426e7f37ad";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC direct diagnostic fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC direct diagnostic"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC direct diagnostic candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-direct-diag-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC direct diagnostic worktree add failed"}
 Set-Location -LiteralPath $temp
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "UNC direct diagnostic Release build failed"}
 $env:FLY_MIGRATION_CONFIGURATION="Release"
 $env:PYTHONPATH=Join-Path $temp "tests\winui"
 & python -u -X utf8 .\tests\winui\test_unc_transfer_gui.py
 $rc=$LASTEXITCODE
 Write-Host "UNC_DIRECT_DIAGNOSTIC_EXIT=$rc"
 if($rc -ne 0){exit $rc}
}finally{
 Remove-Item Env:FLY_MIGRATION_CONFIGURATION -ErrorAction SilentlyContinue
 Remove-Item Env:PYTHONPATH -ErrorAction SilentlyContinue
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
